import { useEffect, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
import { AlertTriangle, ArrowRight, Award, BarChart3, BookOpen, Check, ChevronLeft, ClipboardCheck, Download, Edit3, Eye, FileText, GraduationCap, LayoutDashboard, Library, Lock, Menu, MoreHorizontal, NotebookPen, Plus, Save, Search, ShieldCheck, Trash2, Users, X } from "lucide-react";
import { toast } from "sonner";
import { TopBar } from "@/components/layout/TopBar";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from "@/components/ui/dropdown-menu";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Switch } from "@/components/ui/switch";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Textarea } from "@/components/ui/textarea";
import { academyParticipants, academyProcesses, initialGroup, learningSteps, quizQuestions } from "@/features/academy/data";
import { EmptyState, PersonalNoteCard, ProcessLearningStep, TrainingProcessCard, TrainingProgressBar, TrainingStatusBadge } from "@/features/academy/components";
import { useAcademyStore } from "@/features/academy/store";
import type { AcademyRole, PersonalNote, ProcessLearningContent, QuizQuestionContent, TrainingGroup } from "@/features/academy/types";
import { cn } from "@/lib/utils";

interface Props { onLogout: () => void }
type View = "overview" | "trail" | "catalog" | "notes" | "certificates" | "content" | "groups" | "tracking";

const learnerNav = [
  { id: "overview" as View, label: "Visão geral", icon: LayoutDashboard },
  { id: "trail" as View, label: "Minha trilha", icon: BookOpen },
  { id: "catalog" as View, label: "Consulta de processos", icon: Library },
  { id: "notes" as View, label: "Minhas anotações", icon: NotebookPen },
  { id: "certificates" as View, label: "Certificações", icon: Award },
];
const managerNav = [
  { id: "content" as View, label: "Conteúdos dos processos", icon: Edit3 },
  { id: "groups" as View, label: "Grupos de treinamento", icon: Users },
  { id: "tracking" as View, label: "Acompanhamento", icon: BarChart3 },
];

export function ProcessAcademy({ onLogout }: Props) {
  const navigate = useNavigate();
  const store = useAcademyStore();
  const [role, setRole] = useState<AcademyRole>(() => (localStorage.getItem("academy-role") as AcademyRole) || "manager");
  const [view, setView] = useState<View>(role === "manager" ? "overview" : "overview");
  const [mobileNav, setMobileNav] = useState(false);
  const [learningProcessId, setLearningProcessId] = useState<string>();
  const [groupEditor, setGroupEditor] = useState<TrainingGroup | null>(null);

  const changeRole = (next: AcademyRole) => { setRole(next); localStorage.setItem("academy-role", next); setView("overview"); setLearningProcessId(undefined); };
  const openProcess = (id: string) => setLearningProcessId(id);

  return (
    <div className="min-h-screen bg-background">
      <TopBar onLogout={onLogout} />
      <div className="flex min-h-[calc(100vh-56px)]">
        <aside className={cn("fixed inset-y-14 left-0 z-30 w-64 border-r bg-card p-4 transition-transform lg:sticky lg:top-14 lg:h-[calc(100vh-56px)] lg:translate-x-0", mobileNav ? "translate-x-0" : "-translate-x-full")}>
          <div className="mb-5 flex items-center justify-between px-2"><button onClick={() => navigate("/")} className="flex items-center gap-2 text-sm text-muted-foreground hover:text-primary"><ChevronLeft className="h-4 w-4" />Tela inicial</button><Button variant="ghost" size="icon" className="lg:hidden" onClick={() => setMobileNav(false)}><X className="h-4 w-4" /></Button></div>
          <div className="mb-6 flex items-center gap-3 rounded-xl bg-primary p-3 text-white"><div className="flex h-9 w-9 items-center justify-center rounded-lg bg-white/15"><GraduationCap className="h-5 w-5" /></div><div><div className="text-sm font-semibold">Academia</div><div className="text-xs text-white/70">de Processos</div></div></div>
          <nav className="space-y-1">{[...learnerNav, ...(role === "manager" ? managerNav : [])].map((item) => <button key={item.id} onClick={() => { setView(item.id); setLearningProcessId(undefined); setMobileNav(false); }} className={cn("flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-sm transition", view === item.id && !learningProcessId ? "bg-primary/10 font-medium text-primary" : "text-muted-foreground hover:bg-muted hover:text-foreground")}><item.icon className="h-4 w-4" />{item.label}</button>)}</nav>
          <div className="absolute bottom-4 left-4 right-4 rounded-xl border bg-muted/40 p-3"><p className="mb-2 text-[11px] font-semibold uppercase tracking-wide">Visualizar como</p><div className="grid grid-cols-2 rounded-lg bg-muted p-1"><button onClick={() => changeRole("manager")} className={cn("rounded-md px-2 py-1.5 text-xs font-medium", role === "manager" && "bg-card text-primary shadow-sm")}>Gestor</button><button onClick={() => changeRole("learner")} className={cn("rounded-md px-2 py-1.5 text-xs font-medium", role === "learner" && "bg-card text-primary shadow-sm")}>Colaborador</button></div></div>
        </aside>
        <main className="min-w-0 flex-1"><div className="border-b bg-card px-5 py-3 lg:hidden"><Button variant="ghost" size="sm" onClick={() => setMobileNav(true)}><Menu className="mr-2 h-4 w-4" />Menu da Academia</Button></div><div className={cn("mx-auto p-5 md:p-8 lg:p-10", learningProcessId ? "max-w-[1440px]" : "max-w-7xl")}>{learningProcessId ? <LearningExperienceV2 processId={learningProcessId} role={role} store={store} onBack={() => setLearningProcessId(undefined)} /> : <AcademyView view={view} role={role} store={store} openProcess={openProcess} editGroup={setGroupEditor} />}</div></main>
      </div>
      <GroupEditor open={!!groupEditor} value={groupEditor} onOpenChange={(open) => !open && setGroupEditor(null)} onSave={(group) => { store.saveGroup(group); setGroupEditor(null); toast.success(group.status === "Publicado" ? "Grupo publicado com sucesso." : "Rascunho salvo com sucesso."); }} />
    </div>
  );
}

function AcademyView({ view, role, store, openProcess, editGroup }: { view: View; role: AcademyRole; store: ReturnType<typeof useAcademyStore>; openProcess: (id: string) => void; editGroup: (group: TrainingGroup) => void }) {
  if (view === "overview") return role === "manager" ? <ManagerOverview store={store} editGroup={editGroup} /> : <LearnerOverview openProcess={openProcess} />;
  if (view === "trail") return <Trail openProcess={openProcess} />;
  if (view === "catalog") return <ProcessCatalog openProcess={openProcess} />;
  if (view === "notes") return <NotesPage store={store} />;
  if (view === "certificates") return <Certificates />;
  if (view === "content") return <ContentLibrary openProcess={openProcess} />;
  if (view === "groups") return <Groups store={store} editGroup={editGroup} />;
  return <Tracking />;
}

const PageHeader = ({ title, description, action }: { title: string; description: string; action?: React.ReactNode }) => <div className="mb-8 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="mb-2 text-sm font-medium text-primary">Academia de Processos</p><h1 className="text-2xl md:text-3xl">{title}</h1><p className="mt-2 max-w-2xl text-sm">{description}</p></div>{action}</div>;
const Metric = ({ label, value, detail, icon: Icon }: { label: string; value: string | number; detail?: string; icon: typeof Users }) => <div className="rounded-xl border bg-card p-5"><div className="flex items-center justify-between"><span className="text-sm text-muted-foreground">{label}</span><div className="rounded-lg bg-primary/10 p-2"><Icon className="h-4 w-4 text-primary" /></div></div><div className="mt-3 text-2xl font-semibold">{value}</div>{detail && <p className="mt-1 text-xs">{detail}</p>}</div>;

function LearnerOverview({ openProcess }: { openProcess: (id: string) => void }) {
  const current = academyProcesses[1];
  return <><PageHeader title="Academia de Processos" description="Aprenda os processos da sua função e consulte as instruções sempre que precisar." /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Em andamento" value={1} detail="Continue de onde parou" icon={BookOpen} /><Metric label="Pendentes" value={2} detail="Dentro do prazo" icon={FileText} /><Metric label="Processos concluídos" value={1} detail="25% da trilha" icon={ClipboardCheck} /><Metric label="Certificações" value={0} detail="1 em andamento" icon={Award} /></div><section className="mt-9"><h2 className="mb-4 text-lg">Continuar aprendendo</h2><div className="overflow-hidden rounded-2xl bg-primary p-6 text-white md:p-8"><div className="flex flex-col justify-between gap-6 md:flex-row md:items-center"><div className="max-w-2xl"><span className="rounded-full bg-white/15 px-3 py-1 text-xs">Analistas de Plano de Contabilidade</span><h2 className="mt-4 text-2xl text-white">{current.name}</h2><p className="mt-2 text-sm text-white/75">Retome a partir da etapa “Cadastrar a nova conta”.</p><div className="mt-5 max-w-lg"><div className="mb-2 flex justify-between text-xs"><span>Progresso</span><span>60%</span></div><div className="h-2 rounded-full bg-white/20"><div className="h-full w-3/5 rounded-full bg-white" /></div></div></div><div className="shrink-0"><div className="mb-3 text-sm text-white/70">Duração estimada: 25 min</div><Button variant="secondary" onClick={() => openProcess(current.id)}>Continuar treinamento</Button></div></div></div></section><section className="mt-9"><div className="mb-4 flex items-center justify-between"><h2 className="text-lg">Minha trilha</h2><span className="text-sm text-muted-foreground">4 processos</span></div><div className="grid gap-4 lg:grid-cols-2">{academyProcesses.slice(0, 4).map((process) => <TrainingProcessCard key={process.id} process={process} onOpen={() => openProcess(process.id)} />)}</div></section></>;
}

function ManagerOverview({ store, editGroup }: { store: ReturnType<typeof useAcademyStore>; editGroup: (g: TrainingGroup) => void }) {
  return <><PageHeader title="Visão geral" description="Acompanhe a capacitação das equipes e mantenha o conhecimento operacional atualizado." action={<Button onClick={() => editGroup({ ...initialGroup, id: `group-${Date.now()}`, name: "", status: "Rascunho", participantIds: [], processIds: [] })}><Plus className="mr-2 h-4 w-4" />Criar grupo</Button>} /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-5"><Metric label="Grupos ativos" value={store.groups.filter((g) => g.status === "Publicado").length} icon={Users} /><Metric label="Participantes" value={4} icon={Users} /><Metric label="Conclusão geral" value="63%" icon={ClipboardCheck} /><Metric label="Taxa de aprovação" value="82%" icon={Award} /><Metric label="Atrasados" value={1} icon={FileText} /></div><div className="mt-8 grid gap-6 xl:grid-cols-[1.35fr_1fr]"><section className="rounded-xl border bg-card p-6"><div className="mb-5 flex items-center justify-between"><div><h2 className="text-lg">Progresso do grupo</h2><p className="mt-1 text-sm">Analistas de Plano de Contabilidade</p></div><TrainingStatusBadge status="Publicado" /></div><div className="space-y-4">{academyParticipants.slice(0, 4).map((p) => <div key={p.id}><div className="mb-2 flex justify-between text-sm"><span className="font-medium">{p.name}</span><span className="text-muted-foreground">{p.progress}%</span></div><TrainingProgressBar value={p.progress} label={false} /></div>)}</div></section><section className="rounded-xl border bg-card p-6"><h2 className="text-lg">Processos com maior dificuldade</h2><div className="mt-5 space-y-4"><div className="rounded-lg border p-4"><div className="flex justify-between gap-3"><span className="text-sm font-medium">Criar conta contábil</span><span className="text-sm font-semibold text-amber-700">72%</span></div><p className="mt-2 text-xs">Maior índice de erro: validação de duplicidade</p></div><div className="rounded-lg border p-4"><div className="flex justify-between gap-3"><span className="text-sm font-medium">Alterar conta contábil</span><span className="text-sm font-semibold">81%</span></div><p className="mt-2 text-xs">Maior índice de erro: evidências obrigatórias</p></div></div></section></div></>;
}

function Trail({ openProcess }: { openProcess: (id: string) => void }) { return <><PageHeader title="Minha trilha" description="Acompanhe sua evolução e conclua os processos atribuídos à sua função." /><div className="mb-6 rounded-xl border bg-card p-5"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-center"><div><h2 className="text-lg">Analistas de Plano de Contabilidade</h2><p className="mt-1 text-sm">Prazo: 30 de setembro de 2026 · Nota mínima: 80%</p></div><div className="min-w-52"><div className="mb-2 flex justify-between text-xs"><span>Progresso da trilha</span><span>38%</span></div><TrainingProgressBar value={38} label={false} /></div></div></div><div className="grid gap-4 lg:grid-cols-2">{academyProcesses.map((process) => <TrainingProcessCard key={process.id} process={process} onOpen={() => openProcess(process.id)} />)}</div></> }

function ProcessCatalog({ openProcess }: { openProcess: (id: string) => void }) { const [search, setSearch] = useState(""); const [area, setArea] = useState("all"); const filtered = academyProcesses.filter((p) => p.name.toLowerCase().includes(search.toLowerCase()) && (area === "all" || p.area === area)); return <><PageHeader title="Consulta de processos" description="Consulte rapidamente os processos liberados para você, sem refazer o treinamento." /><div className="mb-6 grid gap-3 rounded-xl border bg-card p-4 md:grid-cols-[1fr_220px_180px]"><div className="relative"><Search className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" /><Input className="pl-9" placeholder="Pesquisar processo..." value={search} onChange={(e) => setSearch(e.target.value)} /></div><Select value={area} onValueChange={setArea}><SelectTrigger><SelectValue placeholder="Área" /></SelectTrigger><SelectContent><SelectItem value="all">Todas as áreas</SelectItem><SelectItem value="Contabilidade">Contabilidade</SelectItem></SelectContent></Select><Select defaultValue="all"><SelectTrigger><SelectValue placeholder="Status" /></SelectTrigger><SelectContent><SelectItem value="all">Todos os status</SelectItem><SelectItem value="done">Concluídos</SelectItem><SelectItem value="favorite">Favoritos</SelectItem></SelectContent></Select></div>{filtered.length ? <div className="grid gap-4 lg:grid-cols-2">{filtered.map((process) => <article key={process.id} className="rounded-xl border bg-card p-5"><div className="flex items-start justify-between"><div><span className="rounded-full bg-violet-50 px-2.5 py-1 text-xs font-medium text-violet-700">Modo consulta</span><h3 className="mt-3 text-base font-semibold">{process.name}</h3><p className="mt-1 text-xs">{process.code} · {process.systems.join(", ")}</p></div><BookOpen className="h-5 w-5 text-primary" /></div><p className="mt-4 text-sm">{process.objective}</p><Button className="mt-5 w-full" variant="outline" onClick={() => openProcess(process.id)}>Consultar processo</Button></article>)}</div> : <EmptyState title="Nenhum processo encontrado" description="Tente ajustar sua pesquisa ou os filtros selecionados." />}</> }

function ContentLibrary({ openProcess }: { openProcess: (id: string) => void }) { const [search, setSearch] = useState(""); const filtered = academyProcesses.filter((process) => process.name.toLowerCase().includes(search.toLowerCase())); return <><PageHeader title="Conteúdos dos processos" description="Revise e adapte a experiência didática de cada treinamento, preservando a SOP vigente como fonte oficial." /><div className="mb-6 rounded-xl border bg-card p-4"><div className="relative max-w-xl"><Search className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" /><Input className="pl-9" placeholder="Pesquisar conteúdo de treinamento..." value={search} onChange={(event) => setSearch(event.target.value)} /></div></div><div className="grid gap-4 lg:grid-cols-2">{filtered.map((process) => <article key={process.id} className="rounded-2xl border bg-card p-5 transition hover:border-primary/30 hover:shadow-sm"><div className="flex items-start gap-4"><div className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl bg-primary/10"><Edit3 className="h-5 w-5 text-primary" /></div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><h3 className="text-base font-semibold">{process.name}</h3><TrainingStatusBadge status="Publicado" /></div><p className="mt-1 text-xs">{process.code} · {process.area} · SOP {process.sopVersion}</p><p className="mt-3 text-sm">Edite visão geral, preparação, pontos de atenção, resumo e quiz.</p><div className="mt-4 flex gap-2"><Button onClick={() => openProcess(process.id)}><Edit3 className="mr-2 h-4 w-4" />Abrir e editar</Button><Button variant="outline" onClick={() => openProcess(process.id)}><Eye className="mr-2 h-4 w-4" />Visualizar</Button></div></div></div></article>)}</div></>; }

function Groups({ store, editGroup }: { store: ReturnType<typeof useAcademyStore>; editGroup: (g: TrainingGroup) => void }) {
  const [archiveId, setArchiveId] = useState<string>();
  return <><PageHeader title="Grupos de treinamento" description="Crie trilhas, atribua participantes e defina as regras de conclusão." action={<Button onClick={() => editGroup({ ...initialGroup, id: `group-${Date.now()}`, name: "", status: "Rascunho", participantIds: [], processIds: [] })}><Plus className="mr-2 h-4 w-4" />Criar grupo</Button>} /><div className="overflow-x-auto rounded-xl border bg-card"><table className="w-full min-w-[900px] text-left text-sm"><thead className="bg-muted/50 text-xs text-muted-foreground"><tr>{["Grupo", "Área / cargo", "Participantes", "Processos", "Progresso", "Status", "Responsável", ""].map((h) => <th key={h} className="px-4 py-3 font-medium">{h}</th>)}</tr></thead><tbody>{store.groups.map((g) => <tr key={g.id} className="border-t"><td className="px-4 py-4 font-medium">{g.name}</td><td className="px-4 py-4 text-muted-foreground">{g.department}<br /><span className="text-xs">{g.role}</span></td><td className="px-4 py-4">{g.participantIds.length}</td><td className="px-4 py-4">{g.processIds.length}</td><td className="w-36 px-4 py-4"><TrainingProgressBar value={g.status === "Publicado" ? 63 : 0} /></td><td className="px-4 py-4"><TrainingStatusBadge status={g.status} /></td><td className="px-4 py-4">{g.owner}</td><td className="px-4 py-4"><DropdownMenu><DropdownMenuTrigger asChild><Button variant="ghost" size="icon"><MoreHorizontal className="h-4 w-4" /></Button></DropdownMenuTrigger><DropdownMenuContent align="end"><DropdownMenuItem onClick={() => editGroup(g)}><Eye className="mr-2 h-4 w-4" />Visualizar / editar</DropdownMenuItem><DropdownMenuItem onClick={() => { store.duplicateGroup(g.id); toast.success("Grupo duplicado como rascunho."); }}><Plus className="mr-2 h-4 w-4" />Duplicar</DropdownMenuItem><DropdownMenuItem className="text-destructive" onClick={() => setArchiveId(g.id)}><Trash2 className="mr-2 h-4 w-4" />Arquivar</DropdownMenuItem></DropdownMenuContent></DropdownMenu></td></tr>)}</tbody></table></div><Dialog open={!!archiveId} onOpenChange={(o) => !o && setArchiveId(undefined)}><DialogContent><DialogHeader><DialogTitle>Arquivar grupo?</DialogTitle><DialogDescription>O grupo deixará de aparecer entre os treinamentos ativos. Os registros de progresso serão preservados.</DialogDescription></DialogHeader><DialogFooter><Button variant="outline" onClick={() => setArchiveId(undefined)}>Cancelar</Button><Button variant="destructive" onClick={() => { if (archiveId) store.archiveGroup(archiveId); setArchiveId(undefined); toast.success("Grupo arquivado."); }}>Arquivar grupo</Button></DialogFooter></DialogContent></Dialog></>;
}

function Tracking() { const [selected, setSelected] = useState<typeof academyParticipants[0]>(); return <><PageHeader title="Acompanhamento" description="Monitore progresso, resultados e pontos que precisam de reforço." /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-6"><Metric label="Atribuídos" value={4} icon={Users} /><Metric label="Iniciaram" value={4} icon={BookOpen} /><Metric label="Concluíram" value={1} icon={ClipboardCheck} /><Metric label="Aprovação" value="82%" icon={Award} /><Metric label="Nota média" value="84%" icon={BarChart3} /><Metric label="Atrasados" value={1} icon={FileText} /></div><div className="mt-6 grid gap-3 rounded-xl border bg-card p-4 md:grid-cols-3 xl:grid-cols-6">{["Grupo", "Cargo", "Área", "Processo", "Status", "Período"].map((label) => <Select key={label} defaultValue="all"><SelectTrigger><SelectValue placeholder={label} /></SelectTrigger><SelectContent><SelectItem value="all">{label}: todos</SelectItem></SelectContent></Select>)}</div><div className="mt-6 overflow-x-auto rounded-xl border bg-card"><table className="w-full min-w-[950px] text-left text-sm"><thead className="bg-muted/50 text-xs text-muted-foreground"><tr>{["Colaborador", "Grupo", "Progresso", "Processos", "Nota média", "Prazo", "Status", "Última atividade"].map((h) => <th className="px-4 py-3 font-medium" key={h}>{h}</th>)}</tr></thead><tbody>{academyParticipants.slice(0, 4).map((p) => <tr className="cursor-pointer border-t hover:bg-muted/30" key={p.id} onClick={() => setSelected(p)}><td className="px-4 py-4 font-medium">{p.name}</td><td className="px-4 py-4">Analistas de Plano...</td><td className="w-36 px-4 py-4"><TrainingProgressBar value={p.progress} /></td><td className="px-4 py-4">{Math.round(p.progress / 25)}/4</td><td className="px-4 py-4">{p.score ? `${p.score}%` : "—"}</td><td className="px-4 py-4">30/09/2026</td><td className="px-4 py-4"><TrainingStatusBadge status={p.status} /></td><td className="px-4 py-4 text-muted-foreground">{p.lastActivity}</td></tr>)}</tbody></table></div><section className="mt-7"><h2 className="mb-4 text-lg">Processos com maior dificuldade</h2><div className="grid gap-4 md:grid-cols-2"><div className="rounded-xl border bg-card p-5"><div className="flex justify-between"><h3 className="text-base font-semibold">Criar conta contábil</h3><span className="font-semibold text-amber-700">72% média</span></div><div className="mt-4 grid grid-cols-3 gap-3 text-sm"><div><p className="text-xs">Avaliados</p><b>12</b></div><div><p className="text-xs">Reprovação</p><b>28%</b></div><div><p className="text-xs">Mais erros</p><b>Duplicidade</b></div></div></div><div className="rounded-xl border bg-card p-5"><div className="flex justify-between"><h3 className="text-base font-semibold">Alterar conta contábil</h3><span className="font-semibold">81% média</span></div><div className="mt-4 grid grid-cols-3 gap-3 text-sm"><div><p className="text-xs">Avaliados</p><b>9</b></div><div><p className="text-xs">Reprovação</p><b>17%</b></div><div><p className="text-xs">Mais erros</p><b>Evidências</b></div></div></div></div></section><Dialog open={!!selected} onOpenChange={(o) => !o && setSelected(undefined)}><DialogContent className="max-w-2xl"><DialogHeader><DialogTitle>{selected?.name}</DialogTitle><DialogDescription>Detalhamento do progresso na trilha.</DialogDescription></DialogHeader><div className="space-y-3">{academyProcesses.map((p, i) => <div key={p.id} className="rounded-lg border p-4"><div className="flex items-center justify-between"><div><div className="text-sm font-medium">{p.name}</div><div className="mt-1 text-xs text-muted-foreground">Leitura: {i < Math.ceil((selected?.progress || 0) / 25) ? "concluída" : "pendente"} · Ciência: {i < Math.floor((selected?.progress || 0) / 25) ? "registrada" : "pendente"} · Tentativas: {i === 0 ? 1 : 0}</div></div><TrainingStatusBadge status={i < Math.floor((selected?.progress || 0) / 25) ? "Concluído" : i === Math.floor((selected?.progress || 0) / 25) ? "Em andamento" : "Não iniciado"} /></div></div>)}</div></DialogContent></Dialog></> }

function NotesPage({ store }: { store: ReturnType<typeof useAcademyStore> }) { const [search, setSearch] = useState(""); const [category, setCategory] = useState("all"); const [editing, setEditing] = useState<PersonalNote | null>(null); const filtered = store.notes.filter((n) => n.content.toLowerCase().includes(search.toLowerCase()) && (category === "all" || n.category === category)); return <><PageHeader title="Minhas anotações" description="Suas anotações são privadas e ficam vinculadas à versão da SOP consultada." action={<Button onClick={() => setEditing({ id: `note-${Date.now()}`, processId: academyProcesses[1].id, processName: academyProcesses[1].name, category: "Lembrete", content: "", pinned: false, sopVersion: academyProcesses[1].sopVersion, createdAt: new Date().toLocaleDateString("pt-BR"), updatedAt: new Date().toLocaleDateString("pt-BR") })}><Plus className="mr-2 h-4 w-4" />Nova anotação</Button>} /><div className="mb-6 grid gap-3 rounded-xl border bg-card p-4 md:grid-cols-[1fr_220px]"><div className="relative"><Search className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" /><Input className="pl-9" placeholder="Pesquisar nas anotações..." value={search} onChange={(e) => setSearch(e.target.value)} /></div><Select value={category} onValueChange={setCategory}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="all">Todas as categorias</SelectItem><SelectItem value="Importante">Importante</SelectItem><SelectItem value="Dúvida">Dúvida</SelectItem><SelectItem value="Lembrete">Lembrete</SelectItem></SelectContent></Select></div>{filtered.length ? <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{filtered.sort((a, b) => Number(b.pinned) - Number(a.pinned)).map((note) => <PersonalNoteCard key={note.id} note={note} onEdit={() => setEditing(note)} onDelete={() => { store.deleteNote(note.id); toast.success("Anotação excluída."); }} onPin={() => store.togglePin(note.id)} />)}</div> : <EmptyState title="Nenhuma anotação encontrada" description="Crie anotações durante o treinamento ou ajuste os filtros." />}<NoteDialog note={editing} onClose={() => setEditing(null)} onSave={(n) => { store.saveNote(n); setEditing(null); toast.success("Anotação salva."); }} /></> }

function NoteDialog({ note, onClose, onSave }: { note: PersonalNote | null; onClose: () => void; onSave: (n: PersonalNote) => void }) { const [content, setContent] = useState(""); const [category, setCategory] = useState<PersonalNote["category"]>("Lembrete"); if (note && content === "" && note.content) setTimeout(() => { setContent(note.content); setCategory(note.category); }, 0); return <Dialog open={!!note} onOpenChange={(o) => { if (!o) { setContent(""); onClose(); } }}><DialogContent><DialogHeader><DialogTitle>{note?.content ? "Editar anotação" : "Nova anotação"}</DialogTitle><DialogDescription>Somente você poderá visualizar este conteúdo.</DialogDescription></DialogHeader><div className="space-y-4"><div><Label>Categoria</Label><Select value={category} onValueChange={(v) => setCategory(v as PersonalNote["category"])}><SelectTrigger className="mt-2"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="Importante">Importante</SelectItem><SelectItem value="Dúvida">Dúvida</SelectItem><SelectItem value="Lembrete">Lembrete</SelectItem></SelectContent></Select></div><div><Label>Anotação</Label><Textarea className="mt-2 min-h-32" value={content} onChange={(e) => setContent(e.target.value)} placeholder="Escreva sua anotação..." /></div></div><DialogFooter><Button variant="outline" onClick={onClose}>Cancelar</Button><Button disabled={!content.trim()} onClick={() => note && onSave({ ...note, content, category, updatedAt: new Date().toLocaleDateString("pt-BR") })}>Salvar anotação</Button></DialogFooter></DialogContent></Dialog> }

function Certificates() { const [preview, setPreview] = useState(false); return <><PageHeader title="Certificações" description="Consulte os treinamentos concluídos e a validade de suas certificações." /><div className="grid gap-4 lg:grid-cols-2"><article className="rounded-xl border bg-card p-6"><div className="flex items-start justify-between"><div className="flex gap-3"><div className="rounded-xl bg-emerald-50 p-3"><Award className="h-6 w-6 text-emerald-700" /></div><div><h3 className="text-base font-semibold">Fundamentos de Contabilidade</h3><p className="mt-1 text-xs">Emitido para Carla Mendes</p></div></div><TrainingStatusBadge status="Válida" /></div><div className="mt-5 grid grid-cols-3 gap-3 border-y py-4 text-sm"><div><p className="text-xs">Conclusão</p><b>18/08/2026</b></div><div><p className="text-xs">Processos</p><b>4</b></div><div><p className="text-xs">Nota final</p><b>94%</b></div></div><div className="mt-4 flex gap-2"><Button variant="outline" className="flex-1" onClick={() => setPreview(true)}><Eye className="mr-2 h-4 w-4" />Visualizar</Button><Button className="flex-1" onClick={() => toast.success("Download do certificado simulado com sucesso.")}><Download className="mr-2 h-4 w-4" />Baixar</Button></div></article></div><Dialog open={preview} onOpenChange={setPreview}><DialogContent className="max-w-2xl"><div className="rounded-xl border-4 border-double border-primary/25 bg-white px-8 py-12 text-center"><GraduationCap className="mx-auto h-12 w-12 text-primary" /><div className="mt-5 text-sm font-semibold uppercase tracking-[0.25em] text-primary">Certificado de conclusão</div><h2 className="mt-5 text-2xl">Fundamentos de Contabilidade</h2><p className="mt-5 text-sm">Certificamos que <b>Carla Mendes</b> concluiu a trilha com aproveitamento de <b>94%</b>.</p><p className="mt-8 text-xs">ProcessHub · Emitido em 18 de agosto de 2026</p></div></DialogContent></Dialog></> }

function LearningExperienceV2({ processId, role, store, onBack }: { processId: string; role: AcademyRole; store: ReturnType<typeof useAcademyStore>; onBack: () => void }) {
  const process = academyProcesses.find((item) => item.id === processId) || academyProcesses[1];
  const content = store.learningContent[process.id];
  const current = store.progress[process.id] || { processId: process.id, progress: process.progress, understoodSteps: [], readingCompleted: process.progress === 100, acknowledged: process.progress === 100, quizPassed: process.status === "Concluído", attempts: process.score ? 1 : 0, quizScore: process.score };
  const [answers, setAnswers] = useState<Record<number, number>>({});
  const [confirmQuiz, setConfirmQuiz] = useState(false);
  const [result, setResult] = useState<{ score: number; passed: boolean; correct: number }>();
  const [noteStep, setNoteStep] = useState<number>();
  const [editorOpen, setEditorOpen] = useState(false);
  const progress = Math.min(100, Math.max(current.progress, Math.round((current.understoodSteps.length / learningSteps.length) * 55) + (current.readingCompleted ? 15 : 0) + (current.acknowledged ? 10 : 0) + (current.quizPassed ? 20 : 0)));
  const quizUnlocked = current.readingCompleted && current.acknowledged;
  const sections = [
    ["overview", "Visão geral"], ["before", "Antes de começar"], ["steps", "Passo a passo"],
    ["attention", "Pontos de atenção"], ["summary", "Resumo operacional"], ["quiz", "Quiz"],
  ];
  const goTo = (id: string) => document.getElementById(`academy-${id}`)?.scrollIntoView({ behavior: "smooth", block: "start" });
  const toggleStep = (index: number) => {
    const understoodSteps = current.understoodSteps.includes(index) ? current.understoodSteps.filter((item) => item !== index) : [...current.understoodSteps, index];
    store.updateProgress(process.id, { understoodSteps });
    toast.success(current.understoodSteps.includes(index) ? "Etapa marcada para revisão." : "Etapa compreendida. Continue quando quiser.");
  };
  const submitQuiz = () => {
    const correct = content.questions.filter((question, index) => answers[index] === question.correct).length;
    const score = Math.round((correct / content.questions.length) * 100);
    const passed = score >= initialGroup.passingScore;
    setResult({ score, passed, correct });
    store.updateProgress(process.id, { quizScore: score, quizPassed: passed, attempts: current.attempts + 1, progress: passed ? 100 : Math.max(progress, 85), completedAt: passed ? new Date().toISOString() : undefined });
    setConfirmQuiz(false);
    toast.success("Resultado registrado na sua trilha.");
  };

  return <>
    <button onClick={onBack} className="mb-5 flex items-center gap-2 text-sm text-muted-foreground transition hover:text-primary"><ChevronLeft className="h-4 w-4" />Voltar à Academia</button>
    <section className="relative mb-7 overflow-hidden rounded-3xl bg-[#07155f] px-6 py-7 text-white shadow-[0_18px_50px_rgba(7,21,95,0.18)] md:px-9 md:py-9">
      <div className="absolute -right-16 -top-24 h-64 w-64 rounded-full bg-[#3146e8]/40 blur-2xl" />
      <div className="absolute -bottom-28 right-48 h-56 w-56 rounded-full bg-cyan-400/15 blur-3xl" />
      <div className="relative flex flex-col justify-between gap-8 lg:flex-row lg:items-end">
        <div className="max-w-3xl"><div className="mb-4 flex flex-wrap items-center gap-2"><span className="rounded-full border border-white/15 bg-white/10 px-3 py-1 text-xs font-medium">Trilha · Analistas de Plano de Contabilidade</span><span className="rounded-full bg-emerald-400/15 px-3 py-1 text-xs font-medium text-emerald-200">{current.quizPassed ? "Concluído" : "Em andamento"}</span></div><p className="mb-2 text-sm text-white/60">{process.code} · {process.area} · SOP {process.sopVersion}</p><h1 className="text-3xl font-semibold tracking-tight text-white md:text-4xl">{process.name}</h1><p className="mt-3 max-w-2xl text-sm leading-6 text-white/70">{content.overview.objective}</p><div className="mt-6 flex flex-wrap gap-5 text-xs text-white/65"><span>{process.minutes} minutos</span><span>{learningSteps.length} etapas práticas</span><span>{content.questions.length} questões</span></div></div>
        <div className="w-full rounded-2xl border border-white/10 bg-white/[0.08] p-5 backdrop-blur lg:w-80"><div className="mb-3 flex items-center justify-between text-sm"><span className="text-white/70">Seu progresso</span><strong className="text-lg text-white">{progress}%</strong></div><div className="h-2.5 overflow-hidden rounded-full bg-white/15"><div className="h-full rounded-full bg-gradient-to-r from-cyan-300 to-emerald-300 transition-all" style={{ width: `${progress}%` }} /></div><p className="mt-3 text-xs text-white/60">{current.understoodSteps.length} de {learningSteps.length} etapas compreendidas</p>{role === "manager" && <Button className="mt-5 w-full border-white/20 bg-white text-[#07155f] hover:bg-white/90" onClick={() => setEditorOpen(true)}><Edit3 className="mr-2 h-4 w-4" />Editar conteúdo</Button>}</div>
      </div>
    </section>

    <div className="grid items-start gap-7 xl:grid-cols-[minmax(0,1fr)_260px]">
      <div className="space-y-6">
        <LearningChapter id="overview" number="01" eyebrow="Contexto" title="Entenda o processo" description="Comece pelo propósito, pelas entradas e pelo resultado esperado.">
          <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-4">{[["Objetivo", content.overview.objective], ["Resultado esperado", content.overview.expectedResult], ["Frequência", content.overview.frequency], ["Seu papel", content.overview.userRole], ["Sistemas", content.overview.systems], ["Entradas", content.overview.inputs], ["Saídas", content.overview.outputs], ["Tempo médio", content.overview.averageTime]].map(([label, value]) => <div key={label} className="rounded-2xl border border-slate-100 bg-slate-50/70 p-4"><div className="text-[11px] font-semibold uppercase tracking-[0.08em] text-slate-500">{label}</div><p className="mt-2 text-sm leading-5 text-slate-800">{value}</p></div>)}</div>
          <NextChapter label="Preparar acessos e documentos" onClick={() => goTo("before")} />
        </LearningChapter>

        <LearningChapter id="before" number="02" eyebrow="Preparação" title="Antes de começar" description="Confira estes itens uma única vez antes de iniciar a execução.">
          <div className="grid gap-3 md:grid-cols-2">{content.beforeYouStart.map((item, index) => <div key={`${item}-${index}`} className="flex items-center gap-3 rounded-2xl border border-emerald-100 bg-emerald-50/50 p-4"><span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-emerald-100 text-emerald-700"><Check className="h-4 w-4" /></span><span className="text-sm font-medium text-emerald-950">{item}</span></div>)}</div>
          <NextChapter label="Ver o passo a passo" onClick={() => goTo("steps")} />
        </LearningChapter>

        <LearningChapter id="steps" number="03" eyebrow="Execução" title="Passo a passo" description="Todas as etapas estão abertas para leitura. Marque apenas o que já estiver claro.">
          <div className="relative space-y-4 before:absolute before:bottom-8 before:left-5 before:top-8 before:w-px before:bg-slate-200">{learningSteps.map((step, index) => <article key={step.title} className={cn("relative rounded-2xl border bg-white p-5 pl-16 transition", current.understoodSteps.includes(index) ? "border-emerald-200 shadow-[0_8px_24px_rgba(16,185,129,0.06)]" : "border-slate-200")}><span className={cn("absolute left-4 top-5 z-10 flex h-9 w-9 items-center justify-center rounded-full border-4 border-white text-sm font-semibold", current.understoodSteps.includes(index) ? "bg-emerald-500 text-white" : "bg-primary text-white")}>{current.understoodSteps.includes(index) ? <Check className="h-4 w-4" /> : index + 1}</span><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-start"><div><h3 className="text-base font-semibold text-slate-950">{step.title}</h3><p className="mt-2 text-sm leading-6 text-slate-600">{step.description}</p></div><span className="shrink-0 rounded-full bg-slate-100 px-3 py-1 text-xs text-slate-600">{step.system}</span></div><div className="mt-4 grid gap-2 sm:grid-cols-3">{[["Entrada", step.input], ["Saída", step.output], ["Evidência", step.evidence]].map(([label, value]) => <div key={label} className="rounded-xl bg-slate-50 p-3"><span className="text-[10px] font-semibold uppercase tracking-wide text-slate-500">{label}</span><div className="mt-1 text-xs font-medium text-slate-800">{value}</div></div>)}</div><div className="mt-4 flex items-start gap-2 rounded-xl bg-amber-50 p-3 text-xs leading-5 text-amber-900"><AlertTriangle className="mt-0.5 h-4 w-4 shrink-0" />{step.attention}</div><div className="mt-4 flex flex-wrap gap-2"><Button size="sm" variant={current.understoodSteps.includes(index) ? "secondary" : "default"} onClick={() => toggleStep(index)}>{current.understoodSteps.includes(index) ? <><Check className="mr-2 h-4 w-4" />Compreendida</> : "Marcar como compreendida"}</Button><Button size="sm" variant="ghost" onClick={() => setNoteStep(index)}>Adicionar anotação</Button></div></article>)}</div>
          <NextChapter label="Revisar pontos de atenção" onClick={() => goTo("attention")} />
        </LearningChapter>

        <LearningChapter id="attention" number="04" eyebrow="Controles" title="Pontos de atenção" description="Cuidados que ajudam a executar o processo com segurança.">
          <div className="grid gap-3 md:grid-cols-2">{content.attentionPoints.map((point, index) => <div key={`${point.title}-${index}`} className="rounded-2xl border border-amber-100 bg-gradient-to-br from-amber-50 to-white p-5"><div className="mb-3 flex h-9 w-9 items-center justify-center rounded-xl bg-amber-100"><ShieldCheck className="h-5 w-5 text-amber-700" /></div><h3 className="text-sm font-semibold text-amber-950">{point.title}</h3><p className="mt-2 text-sm leading-6 text-amber-900/80">{point.description}</p></div>)}</div>
          <NextChapter label="Concluir a leitura" onClick={() => goTo("summary")} />
        </LearningChapter>

        <LearningChapter id="summary" number="05" eyebrow="Fechamento" title="Resumo operacional" description="Uma visão rápida para consultar durante a rotina.">
          <div className="grid gap-5 lg:grid-cols-[1.15fr_.85fr]"><div className="grid gap-3 sm:grid-cols-2"><SummaryRow label="Essencial" value={content.operationalSummary.essentials} /><SummaryRow label="Responsáveis" value={content.operationalSummary.owners} /><SummaryRow label="Sistemas" value={content.operationalSummary.systems} /><SummaryRow label="Aprovações" value={content.operationalSummary.approvals} /><SummaryRow label="Evidências" value={content.operationalSummary.evidence} /><SummaryRow label="Checklist final" value={content.operationalSummary.finalChecklist.join(" · ")} /></div><div className="rounded-2xl bg-[#f4f6ff] p-5 ring-1 ring-primary/10"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-primary text-white"><BookOpen className="h-5 w-5" /></div><h3 className="mt-4 text-base font-semibold">Concluir leitura</h3><p className="mt-2 text-sm leading-6">Registre a leitura e a ciência para liberar a avaliação.</p><Button className="mt-5 w-full" variant={current.readingCompleted ? "secondary" : "default"} onClick={() => { store.updateProgress(process.id, { readingCompleted: true }); toast.success("Leitura registrada."); }}>{current.readingCompleted ? <><Check className="mr-2 h-4 w-4" />Leitura concluída</> : "Concluir leitura"}</Button><label className={cn("mt-3 flex items-start gap-3 rounded-xl border bg-white p-3 text-sm", !current.readingCompleted && "cursor-not-allowed opacity-50")}><Checkbox disabled={!current.readingCompleted} checked={current.acknowledged} onCheckedChange={(checked) => { store.updateProgress(process.id, { acknowledged: checked === true }); if (checked) toast.success("Ciência registrada. O quiz está liberado."); }} /><span>Confirmo que li e compreendi este processo.</span></label></div></div>
          <NextChapter label="Responder ao quiz" onClick={() => goTo("quiz")} disabled={!quizUnlocked} />
        </LearningChapter>

        <LearningChapter id="quiz" number="06" eyebrow="Conhecimento" title="Quiz" description="Responda todas as questões nesta página e envie quando estiver pronto.">
          {!quizUnlocked ? <div className="rounded-2xl border border-dashed bg-slate-50 px-6 py-10 text-center"><Lock className="mx-auto h-8 w-8 text-slate-400" /><h3 className="mt-3 font-semibold">Avaliação ainda bloqueada</h3><p className="mt-2 text-sm">Conclua a leitura e registre sua ciência na seção anterior.</p><Button className="mt-4" variant="outline" onClick={() => goTo("summary")}>Ir para conclusão da leitura</Button></div> : result ? <QuizResultV2 result={result} total={content.questions.length} attempts={current.attempts + 1} onReview={() => { setResult(undefined); goTo("steps"); }} onRetry={() => { setResult(undefined); setAnswers({}); }} /> : <div className="space-y-5">{content.questions.map((question, questionIndex) => <article key={question.id} className="rounded-2xl border border-slate-200 p-5 md:p-6"><div className="mb-4 flex items-start gap-3"><span className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-primary/10 text-sm font-semibold text-primary">{questionIndex + 1}</span><div><h3 className="text-base font-semibold leading-6">{question.statement}</h3><p className="mt-1 text-xs text-muted-foreground">Referência: {question.reference}</p></div></div><div className="grid gap-2 sm:grid-cols-2">{question.options.map((option, optionIndex) => <button key={`${option}-${optionIndex}`} onClick={() => setAnswers({ ...answers, [questionIndex]: optionIndex })} className={cn("rounded-xl border p-3.5 text-left text-sm transition hover:border-primary/40 hover:bg-primary/[0.02]", answers[questionIndex] === optionIndex && "border-primary bg-primary/5 ring-1 ring-primary")}><span className="mr-2 font-semibold text-primary">{String.fromCharCode(65 + optionIndex)}.</span>{option}</button>)}</div></article>)}<div className="sticky bottom-4 flex items-center justify-between gap-4 rounded-2xl border bg-white/95 p-4 shadow-[0_14px_40px_rgba(15,23,42,0.12)] backdrop-blur"><div className="text-sm"><strong>{Object.keys(answers).length}</strong> de {content.questions.length} respondidas</div><Button disabled={Object.keys(answers).length < content.questions.length} onClick={() => setConfirmQuiz(true)}>Finalizar avaliação<ArrowRight className="ml-2 h-4 w-4" /></Button></div></div>}
        </LearningChapter>
      </div>

      <aside className="sticky top-20 hidden rounded-2xl border bg-white p-4 shadow-sm xl:block"><div className="px-2 pb-3 text-xs font-semibold uppercase tracking-[0.12em] text-slate-500">Sua jornada</div><nav className="space-y-1">{sections.map(([id, label], index) => <button key={id} onClick={() => goTo(id)} className="flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left text-sm text-slate-600 transition hover:bg-slate-50 hover:text-primary"><span className="flex h-6 w-6 items-center justify-center rounded-full bg-slate-100 text-[11px] font-semibold">{index + 1}</span>{label}</button>)}</nav><div className="mt-4 rounded-xl bg-slate-50 p-3"><div className="mb-2 flex justify-between text-xs"><span>Progresso</span><strong>{progress}%</strong></div><TrainingProgressBar value={progress} label={false} /></div>{role === "manager" && <Button variant="outline" className="mt-3 w-full" onClick={() => setEditorOpen(true)}><Edit3 className="mr-2 h-4 w-4" />Editar conteúdo</Button>}</aside>
    </div>

    <NoteDialog note={noteStep === undefined ? null : { id: `note-${Date.now()}`, processId: process.id, processName: process.name, step: learningSteps[noteStep].title, category: "Lembrete", content: "", pinned: false, sopVersion: process.sopVersion, createdAt: new Date().toLocaleDateString("pt-BR"), updatedAt: new Date().toLocaleDateString("pt-BR") }} onClose={() => setNoteStep(undefined)} onSave={(note) => { store.saveNote(note); setNoteStep(undefined); toast.success("Anotação privada salva."); }} />
    <Dialog open={confirmQuiz} onOpenChange={setConfirmQuiz}><DialogContent><DialogHeader><DialogTitle>Finalizar avaliação?</DialogTitle><DialogDescription>Suas respostas serão corrigidas e a tentativa ficará registrada.</DialogDescription></DialogHeader><DialogFooter><Button variant="outline" onClick={() => setConfirmQuiz(false)}>Revisar respostas</Button><Button onClick={submitQuiz}>Enviar avaliação</Button></DialogFooter></DialogContent></Dialog>
    <ContentEditor open={editorOpen} content={content} processName={process.name} sopVersion={process.sopVersion} onOpenChange={setEditorOpen} onSave={(next) => { store.saveLearningContent(next); setEditorOpen(false); toast.success("Conteúdo de treinamento atualizado."); }} />
  </>;
}

function LearningChapter({ id, number, eyebrow, title, description, children }: { id: string; number: string; eyebrow: string; title: string; description: string; children: React.ReactNode }) {
  return <section id={`academy-${id}`} className="scroll-mt-20 overflow-hidden rounded-3xl border border-slate-200 bg-white shadow-[0_8px_30px_rgba(15,23,42,0.035)]"><header className="flex items-start gap-4 border-b border-slate-100 px-5 py-5 md:px-7"><span className="text-xl font-semibold text-primary/30">{number}</span><div><div className="text-[11px] font-semibold uppercase tracking-[0.14em] text-primary">{eyebrow}</div><h2 className="mt-1 text-xl font-semibold text-slate-950 md:text-2xl">{title}</h2><p className="mt-1 text-sm text-slate-500">{description}</p></div></header><div className="p-5 md:p-7">{children}</div></section>;
}

function NextChapter({ label, onClick, disabled }: { label: string; onClick: () => void; disabled?: boolean }) { return <div className="mt-6 flex justify-end"><Button variant="ghost" disabled={disabled} onClick={onClick} className="text-primary">{label}<ArrowRight className="ml-2 h-4 w-4" /></Button></div> }

function QuizResultV2({ result, total, attempts, onReview, onRetry }: { result: { score: number; passed: boolean; correct: number }; total: number; attempts: number; onReview: () => void; onRetry: () => void }) { return <div className="rounded-3xl bg-gradient-to-br from-slate-50 to-white p-6 text-center ring-1 ring-slate-200 md:p-9"><div className={cn("mx-auto flex h-16 w-16 items-center justify-center rounded-2xl", result.passed ? "bg-emerald-100" : "bg-amber-100")}>{result.passed ? <Award className="h-8 w-8 text-emerald-700" /> : <BookOpen className="h-8 w-8 text-amber-700" />}</div><h3 className="mt-5 text-xl font-semibold">{result.passed ? "Parabéns! Você concluiu este processo." : "Você está perto. Revise os pontos indicados e tente novamente."}</h3><p className="mx-auto mt-2 max-w-lg text-sm">{result.passed ? "Seu resultado já foi registrado no progresso da trilha." : "O resultado serve para orientar o reforço do conteúdo, sem caráter punitivo."}</p><div className="mx-auto mt-6 grid max-w-lg grid-cols-2 gap-3 sm:grid-cols-4">{[["Nota", `${result.score}%`], ["Mínima", "80%"], ["Acertos", result.correct], ["Erros", total - result.correct]].map(([label, value]) => <div key={label} className="rounded-xl bg-white p-3 ring-1 ring-slate-100"><div className="text-xs text-muted-foreground">{label}</div><div className="mt-1 font-semibold">{value}</div></div>)}</div><p className="mt-5 text-xs">Tentativa {attempts} de {initialGroup.maxAttempts}</p><div className="mt-6 flex flex-wrap justify-center gap-3"><Button variant="outline" onClick={onReview}>Revisar conteúdo</Button>{!result.passed && attempts < initialGroup.maxAttempts && <Button onClick={onRetry}>Realizar nova tentativa</Button>}</div></div> }

function ContentEditor({ open, content, processName, sopVersion, onOpenChange, onSave }: { open: boolean; content: ProcessLearningContent; processName: string; sopVersion: string; onOpenChange: (open: boolean) => void; onSave: (content: ProcessLearningContent) => void }) {
  const [draft, setDraft] = useState(content);
  useEffect(() => { if (open) setDraft(structuredClone(content)); }, [open, content]);
  const setOverview = (key: keyof ProcessLearningContent["overview"], value: string) => setDraft((current) => ({ ...current, overview: { ...current.overview, [key]: value } }));
  const setSummary = (key: keyof Omit<ProcessLearningContent["operationalSummary"], "finalChecklist">, value: string) => setDraft((current) => ({ ...current, operationalSummary: { ...current.operationalSummary, [key]: value } }));
  const updateQuestion = (index: number, patch: Partial<QuizQuestionContent>) => setDraft((current) => ({ ...current, questions: current.questions.map((question, questionIndex) => questionIndex === index ? { ...question, ...patch } : question) }));
  const updateOption = (questionIndex: number, optionIndex: number, value: string) => updateQuestion(questionIndex, { options: draft.questions[questionIndex].options.map((option, index) => index === optionIndex ? value : option) });
  const addQuestion = () => setDraft((current) => ({ ...current, questions: [...current.questions, { id: `${current.processId}-q-${Date.now()}`, statement: "", options: ["", ""], correct: 0, explanation: "", reference: "" }] }));
  const removeQuestion = (index: number) => setDraft((current) => ({ ...current, questions: current.questions.filter((_, questionIndex) => questionIndex !== index) }));
  const valid = Boolean(draft.overview.objective.trim() && draft.beforeYouStart.some((item) => item.trim()) && draft.attentionPoints.length && draft.questions.every((question) => question.statement.trim() && question.options.length >= 2 && question.options.every((option) => option.trim())));
  return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="max-h-[94vh] max-w-5xl overflow-hidden p-0"><DialogHeader className="border-b px-6 py-5"><div className="flex items-start gap-3"><div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-primary/10"><Edit3 className="h-5 w-5 text-primary" /></div><div><DialogTitle>Editar conteúdo do treinamento</DialogTitle><DialogDescription className="mt-1">{processName} · SOP {sopVersion}</DialogDescription></div></div><div className="mt-4 rounded-lg border border-blue-100 bg-blue-50 p-3 text-xs leading-5 text-blue-900">Estas alterações ajustam somente a apresentação didática do treinamento. A SOP vigente continua sendo a fonte oficial do processo.</div></DialogHeader><div className="overflow-y-auto px-6 py-6"><div className="mx-auto max-w-4xl space-y-8">
    <EditorSection number="01" title="Visão geral" description="Adapte o contexto operacional para uma linguagem clara e didática."><div className="grid gap-4 md:grid-cols-2"><EditorField label="Objetivo" wide><Textarea value={draft.overview.objective} onChange={(event) => setOverview("objective", event.target.value)} /></EditorField><EditorField label="Resultado esperado" wide><Textarea value={draft.overview.expectedResult} onChange={(event) => setOverview("expectedResult", event.target.value)} /></EditorField><EditorField label="Frequência"><Input value={draft.overview.frequency} onChange={(event) => setOverview("frequency", event.target.value)} /></EditorField><EditorField label="Papel do usuário"><Input value={draft.overview.userRole} onChange={(event) => setOverview("userRole", event.target.value)} /></EditorField><EditorField label="Sistemas"><Input value={draft.overview.systems} onChange={(event) => setOverview("systems", event.target.value)} /></EditorField><EditorField label="Tempo médio"><Input value={draft.overview.averageTime} onChange={(event) => setOverview("averageTime", event.target.value)} /></EditorField><EditorField label="Entradas"><Input value={draft.overview.inputs} onChange={(event) => setOverview("inputs", event.target.value)} /></EditorField><EditorField label="Saídas"><Input value={draft.overview.outputs} onChange={(event) => setOverview("outputs", event.target.value)} /></EditorField></div></EditorSection>
    <EditorSection number="02" title="Antes de começar" description="Insira um item por linha. Linhas vazias serão ignoradas."><Textarea className="min-h-36" value={draft.beforeYouStart.join("\n")} onChange={(event) => setDraft((current) => ({ ...current, beforeYouStart: event.target.value.split("\n") }))} placeholder="Acesso ao sistema\nDocumento aprovado\nDados necessários" /></EditorSection>
    <EditorSection number="03" title="Pontos de atenção" description="Edite os cuidados que devem ganhar destaque durante o treinamento."><div className="space-y-3">{draft.attentionPoints.map((point, index) => <div key={index} className="grid gap-3 rounded-xl border bg-slate-50/50 p-4 md:grid-cols-[.7fr_1.3fr_auto]"><Input value={point.title} aria-label={`Título do ponto ${index + 1}`} onChange={(event) => setDraft((current) => ({ ...current, attentionPoints: current.attentionPoints.map((item, itemIndex) => itemIndex === index ? { ...item, title: event.target.value } : item) }))} /><Textarea className="min-h-10" value={point.description} aria-label={`Descrição do ponto ${index + 1}`} onChange={(event) => setDraft((current) => ({ ...current, attentionPoints: current.attentionPoints.map((item, itemIndex) => itemIndex === index ? { ...item, description: event.target.value } : item) }))} /><Button variant="ghost" size="icon" aria-label="Remover ponto" onClick={() => setDraft((current) => ({ ...current, attentionPoints: current.attentionPoints.filter((_, itemIndex) => itemIndex !== index) }))}><Trash2 className="h-4 w-4" /></Button></div>)}</div><Button className="mt-3" variant="outline" size="sm" onClick={() => setDraft((current) => ({ ...current, attentionPoints: [...current.attentionPoints, { title: "Novo ponto", description: "" }] }))}><Plus className="mr-2 h-4 w-4" />Adicionar ponto</Button></EditorSection>
    <EditorSection number="04" title="Resumo operacional" description="Monte a ficha curta que será usada na consulta do dia a dia."><div className="grid gap-4 md:grid-cols-2"><EditorField label="Pontos essenciais"><Textarea value={draft.operationalSummary.essentials} onChange={(event) => setSummary("essentials", event.target.value)} /></EditorField><EditorField label="Responsáveis"><Textarea value={draft.operationalSummary.owners} onChange={(event) => setSummary("owners", event.target.value)} /></EditorField><EditorField label="Sistemas"><Input value={draft.operationalSummary.systems} onChange={(event) => setSummary("systems", event.target.value)} /></EditorField><EditorField label="Aprovações"><Input value={draft.operationalSummary.approvals} onChange={(event) => setSummary("approvals", event.target.value)} /></EditorField><EditorField label="Evidências"><Input value={draft.operationalSummary.evidence} onChange={(event) => setSummary("evidence", event.target.value)} /></EditorField><EditorField label="Checklist final"><Textarea value={draft.operationalSummary.finalChecklist.join("\n")} onChange={(event) => setDraft((current) => ({ ...current, operationalSummary: { ...current.operationalSummary, finalChecklist: event.target.value.split("\n") } }))} /></EditorField></div></EditorSection>
    <EditorSection number="05" title="Perguntas do quiz" description="Configure enunciado, alternativas, resposta correta, explicação e referência."><div className="space-y-4">{draft.questions.map((question, questionIndex) => <article key={question.id} className="rounded-2xl border p-5"><div className="mb-4 flex items-center justify-between"><h4 className="font-semibold">Questão {questionIndex + 1}</h4><Button variant="ghost" size="icon" disabled={draft.questions.length === 1} aria-label="Excluir questão" onClick={() => removeQuestion(questionIndex)}><Trash2 className="h-4 w-4" /></Button></div><div className="space-y-4"><EditorField label="Enunciado"><Textarea value={question.statement} onChange={(event) => updateQuestion(questionIndex, { statement: event.target.value })} /></EditorField><div className="space-y-2"><Label>Alternativas</Label>{question.options.map((option, optionIndex) => <div key={optionIndex} className="flex items-center gap-2"><span className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-slate-100 text-xs font-semibold">{String.fromCharCode(65 + optionIndex)}</span><Input value={option} onChange={(event) => updateOption(questionIndex, optionIndex, event.target.value)} /><Button variant="ghost" size="icon" disabled={question.options.length <= 2} aria-label="Remover alternativa" onClick={() => { const options = question.options.filter((_, index) => index !== optionIndex); updateQuestion(questionIndex, { options, correct: Math.min(question.correct, options.length - 1) }); }}><X className="h-4 w-4" /></Button></div>)}<Button variant="ghost" size="sm" onClick={() => updateQuestion(questionIndex, { options: [...question.options, ""] })}><Plus className="mr-2 h-4 w-4" />Adicionar alternativa</Button></div><div className="grid gap-4 md:grid-cols-2"><EditorField label="Resposta correta"><Select value={String(question.correct)} onValueChange={(value) => updateQuestion(questionIndex, { correct: Number(value) })}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{question.options.map((_, optionIndex) => <SelectItem key={optionIndex} value={String(optionIndex)}>Alternativa {String.fromCharCode(65 + optionIndex)}</SelectItem>)}</SelectContent></Select></EditorField><EditorField label="Referência da SOP"><Input value={question.reference} onChange={(event) => updateQuestion(questionIndex, { reference: event.target.value })} /></EditorField></div><EditorField label="Explicação da resposta"><Textarea value={question.explanation} onChange={(event) => updateQuestion(questionIndex, { explanation: event.target.value })} /></EditorField></div></article>)}</div><Button className="mt-4" variant="outline" onClick={addQuestion}><Plus className="mr-2 h-4 w-4" />Adicionar questão</Button></EditorSection>
  </div></div><DialogFooter className="border-t bg-white px-6 py-4"><div className="flex w-full flex-col-reverse justify-between gap-3 sm:flex-row sm:items-center"><span className="text-xs text-muted-foreground">Última atualização: {new Date(content.updatedAt).toLocaleString("pt-BR")}</span><div className="flex gap-2"><Button variant="outline" onClick={() => onOpenChange(false)}>Cancelar</Button><Button disabled={!valid} onClick={() => onSave({ ...draft, beforeYouStart: draft.beforeYouStart.filter((item) => item.trim()), operationalSummary: { ...draft.operationalSummary, finalChecklist: draft.operationalSummary.finalChecklist.filter((item) => item.trim()) } })}><Save className="mr-2 h-4 w-4" />Salvar alterações</Button></div></div></DialogFooter></DialogContent></Dialog>;
}

function EditorSection({ number, title, description, children }: { number: string; title: string; description: string; children: React.ReactNode }) { return <section><div className="mb-4 flex items-start gap-3"><span className="text-lg font-semibold text-primary/35">{number}</span><div><h3 className="text-lg font-semibold">{title}</h3><p className="mt-1 text-sm">{description}</p></div></div>{children}</section> }
function EditorField({ label, children, wide }: { label: string; children: React.ReactNode; wide?: boolean }) { return <div className={wide ? "md:col-span-2" : undefined}><Label>{label}</Label><div className="mt-2">{children}</div></div> }

function LearningExperience({ processId, store, onBack }: { processId: string; store: ReturnType<typeof useAcademyStore>; onBack: () => void }) {
  const process = academyProcesses.find((p) => p.id === processId) || academyProcesses[1];
  const current = store.progress[process.id] || { processId: process.id, progress: process.progress, understoodSteps: [], readingCompleted: process.progress === 100, acknowledged: process.progress === 100, quizPassed: process.status === "Concluído", attempts: process.score ? 1 : 0, quizScore: process.score };
  const [section, setSection] = useState("overview");
  const [noteStep, setNoteStep] = useState<number>();
  const [quizIndex, setQuizIndex] = useState(0);
  const [answers, setAnswers] = useState<Record<number, number>>({});
  const [confirmQuiz, setConfirmQuiz] = useState(false);
  const [result, setResult] = useState<{ score: number; passed: boolean }>();
  const progress = Math.max(current.progress, Math.round((current.understoodSteps.length / learningSteps.length) * 60) + (current.readingCompleted ? 15 : 0) + (current.acknowledged ? 10 : 0) + (current.quizPassed ? 15 : 0));
  const quizUnlocked = current.readingCompleted && current.acknowledged;
  const submitQuiz = () => { const correct = quizQuestions.filter((q, i) => answers[i] === q.correct).length; const score = Math.round((correct / quizQuestions.length) * 100); const passed = score >= initialGroup.passingScore; setResult({ score, passed }); store.updateProgress(process.id, { quizScore: score, quizPassed: passed, attempts: current.attempts + 1, progress: passed ? 100 : Math.max(progress, 85), completedAt: passed ? new Date().toISOString() : undefined }); setConfirmQuiz(false); toast.success("Resultado registrado na sua trilha."); };
  return <><button onClick={onBack} className="mb-5 flex items-center gap-2 text-sm text-muted-foreground hover:text-primary"><ChevronLeft className="h-4 w-4" />Voltar à Academia</button><div className="mb-6 rounded-2xl border bg-card p-6"><div className="flex flex-col justify-between gap-5 md:flex-row md:items-start"><div><div className="mb-3 flex flex-wrap gap-2"><span className="rounded-full bg-primary/10 px-3 py-1 text-xs font-medium text-primary">Modo treinamento</span><TrainingStatusBadge status={current.quizPassed ? "Concluído" : progress > 0 ? "Em andamento" : "Não iniciado"} /></div><h1 className="text-2xl">{process.name}</h1><p className="mt-2 text-sm">{process.code} · {process.area} · SOP {process.sopVersion} · {process.minutes} min</p></div><div className="min-w-64"><div className="mb-2 flex justify-between text-xs"><span>Progresso do treinamento</span><b>{progress}%</b></div><TrainingProgressBar value={progress} label={false} /></div></div></div><Tabs value={section} onValueChange={setSection}><TabsList className="mb-6 h-auto w-full justify-start overflow-x-auto rounded-xl border bg-card p-1"><TabsTrigger value="overview">Visão geral</TabsTrigger><TabsTrigger value="before">Antes de começar</TabsTrigger><TabsTrigger value="steps">Passo a passo</TabsTrigger><TabsTrigger value="attention">Pontos de atenção</TabsTrigger><TabsTrigger value="summary">Resumo operacional</TabsTrigger><TabsTrigger value="quiz">Quiz</TabsTrigger></TabsList><TabsContent value="overview"><LearningPanel title="Visão geral"><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4">{[["Objetivo", process.objective], ["Resultado esperado", process.expectedResult], ["Frequência", "Sob demanda"], ["Papel do usuário", "Analista responsável pela validação e execução"], ["Sistemas", process.systems.join(", ")], ["Entradas", "Solicitação e aprovações"], ["Saídas", "Conta validada ou atualizada"], ["Tempo médio", `${process.minutes} minutos`]].map(([label, value]) => <div key={label} className="rounded-lg bg-muted/50 p-4"><div className="text-xs font-semibold text-muted-foreground">{label}</div><p className="mt-2 text-sm text-foreground">{value}</p></div>)}</div></LearningPanel></TabsContent><TabsContent value="before"><LearningPanel title="Antes de começar"><div className="grid gap-3 md:grid-cols-2">{["Acesso ativo ao SAP S/4HANA", "Perfil autorizado no ServiceNow", "Solicitação com campos obrigatórios", "Aprovação da controladoria", "Documentos de suporte anexados", "Dados da empresa e classificação contábil"].map((item) => <div key={item} className="flex items-center gap-3 rounded-lg border p-4 text-sm"><div className="flex h-6 w-6 items-center justify-center rounded-full bg-emerald-50"><Check className="h-3.5 w-3.5 text-emerald-700" /></div>{item}</div>)}</div></LearningPanel></TabsContent><TabsContent value="steps"><LearningPanel title="Passo a passo"><div className="space-y-3">{learningSteps.map((step, index) => <ProcessLearningStep key={step.title} index={index} step={step} understood={current.understoodSteps.includes(index)} onToggle={() => { const understoodSteps = current.understoodSteps.includes(index) ? current.understoodSteps.filter((i) => i !== index) : [...current.understoodSteps, index]; store.updateProgress(process.id, { understoodSteps }); toast.success(current.understoodSteps.includes(index) ? "Etapa marcada para revisão." : "Etapa marcada como compreendida."); }} onNote={() => setNoteStep(index)} />)}</div></LearningPanel></TabsContent><TabsContent value="attention"><LearningPanel title="Pontos de atenção"><div className="space-y-3">{learningSteps.map((s) => <div key={s.title} className="rounded-lg border-l-4 border-l-amber-400 bg-amber-50 p-4"><div className="text-sm font-semibold text-amber-950">{s.title}</div><p className="mt-1 text-sm text-amber-900">{s.attention}</p></div>)}</div></LearningPanel></TabsContent><TabsContent value="summary"><LearningPanel title="Resumo operacional"><div className="grid gap-5 lg:grid-cols-2"><div className="space-y-3 text-sm"><SummaryRow label="Essencial" value="Validar, pesquisar duplicidade, cadastrar e obter aprovação." /><SummaryRow label="Responsáveis" value="Analista e coordenação contábil" /><SummaryRow label="Sistemas" value={process.systems.join(", ")} /><SummaryRow label="Evidências" value="Checklist, consulta e registro de aprovação" /></div><div className="rounded-xl border bg-muted/30 p-5"><h3 className="text-base font-semibold">Conclusão da leitura</h3><p className="mt-2 text-sm">O quiz será liberado após a leitura e o registro de ciência.</p><Button className="mt-4 w-full" variant={current.readingCompleted ? "secondary" : "default"} onClick={() => { store.updateProgress(process.id, { readingCompleted: true }); toast.success("Leitura registrada."); }}>{current.readingCompleted ? <><Check className="mr-2 h-4 w-4" />Leitura concluída</> : "Marcar leitura como concluída"}</Button><label className={cn("mt-3 flex items-start gap-3 rounded-lg border p-3 text-sm", !current.readingCompleted && "cursor-not-allowed opacity-50")}><Checkbox disabled={!current.readingCompleted} checked={current.acknowledged} onCheckedChange={(checked) => { store.updateProgress(process.id, { acknowledged: checked === true }); if (checked) toast.success("Ciência registrada separadamente do quiz."); }} /><span>Confirmo que li e compreendi a documentação deste processo.</span></label></div></div></LearningPanel></TabsContent><TabsContent value="quiz"><LearningPanel title="Quiz de conhecimento">{!quizUnlocked ? <EmptyState title="Quiz ainda bloqueado" description="Conclua a leitura e registre sua ciência no Resumo operacional para liberar a avaliação." action={<Button onClick={() => setSection("summary")}>Ir para o resumo</Button>} /> : result ? <QuizResultView result={result} attempts={current.attempts + 1} onReview={() => { setSection("steps"); setResult(undefined); }} onRetry={() => { setResult(undefined); setAnswers({}); setQuizIndex(0); }} /> : <div className="mx-auto max-w-2xl"><div className="mb-5 flex justify-between text-sm"><span>Questão {quizIndex + 1} de {quizQuestions.length}</span><span>{Math.round(((quizIndex + 1) / quizQuestions.length) * 100)}%</span></div><TrainingProgressBar value={((quizIndex + 1) / quizQuestions.length) * 100} label={false} /><h3 className="mt-7 text-lg font-semibold">{quizQuestions[quizIndex].statement}</h3><div className="mt-5 space-y-3">{quizQuestions[quizIndex].options.map((option, i) => <button key={option} onClick={() => setAnswers({ ...answers, [quizIndex]: i })} className={cn("w-full rounded-xl border p-4 text-left text-sm transition hover:border-primary/40", answers[quizIndex] === i && "border-primary bg-primary/5 ring-1 ring-primary")}>{option}</button>)}</div><div className="mt-7 flex justify-between"><Button variant="outline" disabled={quizIndex === 0} onClick={() => setQuizIndex((i) => i - 1)}>Voltar</Button>{quizIndex < quizQuestions.length - 1 ? <Button disabled={answers[quizIndex] === undefined} onClick={() => setQuizIndex((i) => i + 1)}>Avançar</Button> : <Button disabled={Object.keys(answers).length < quizQuestions.length} onClick={() => setConfirmQuiz(true)}>Finalizar quiz</Button>}</div></div>}</LearningPanel></TabsContent></Tabs><NoteDialog note={noteStep === undefined ? null : { id: `note-${Date.now()}`, processId: process.id, processName: process.name, step: learningSteps[noteStep].title, category: "Lembrete", content: "", pinned: false, sopVersion: process.sopVersion, createdAt: new Date().toLocaleDateString("pt-BR"), updatedAt: new Date().toLocaleDateString("pt-BR") }} onClose={() => setNoteStep(undefined)} onSave={(note) => { store.saveNote(note); setNoteStep(undefined); toast.success("Anotação privada salva."); }} /><Dialog open={confirmQuiz} onOpenChange={setConfirmQuiz}><DialogContent><DialogHeader><DialogTitle>Finalizar tentativa?</DialogTitle><DialogDescription>Depois do envio, suas respostas serão corrigidas e esta tentativa ficará registrada.</DialogDescription></DialogHeader><DialogFooter><Button variant="outline" onClick={() => setConfirmQuiz(false)}>Revisar respostas</Button><Button onClick={submitQuiz}>Enviar quiz</Button></DialogFooter></DialogContent></Dialog></>;
}

function LearningPanel({ title, children }: { title: string; children: React.ReactNode }) { return <section className="rounded-xl border bg-card p-5 md:p-7"><h2 className="mb-5 text-xl">{title}</h2>{children}</section> }
function SummaryRow({ label, value }: { label: string; value: string }) { return <div className="flex gap-3 rounded-lg border p-4"><Check className="mt-0.5 h-4 w-4 shrink-0 text-emerald-600" /><div><div className="text-xs font-semibold text-muted-foreground">{label}</div><div className="mt-1 text-sm">{value}</div></div></div> }
function QuizResultView({ result, attempts, onReview, onRetry }: { result: { score: number; passed: boolean }; attempts: number; onReview: () => void; onRetry: () => void }) { const correct = Math.round((result.score / 100) * quizQuestions.length); return <div className="mx-auto max-w-xl text-center"><div className={cn("mx-auto flex h-16 w-16 items-center justify-center rounded-full", result.passed ? "bg-emerald-100" : "bg-amber-100")}>{result.passed ? <Award className="h-8 w-8 text-emerald-700" /> : <BookOpen className="h-8 w-8 text-amber-700" />}</div><h3 className="mt-5 text-xl font-semibold">{result.passed ? "Parabéns! Você concluiu este processo." : "Você ainda precisa revisar alguns pontos antes de concluir."}</h3><div className="mt-6 grid grid-cols-4 gap-3">{[["Nota", `${result.score}%`], ["Mínima", "80%"], ["Acertos", correct], ["Erros", quizQuestions.length - correct]].map(([l, v]) => <div key={l} className="rounded-lg bg-muted p-3"><div className="text-xs text-muted-foreground">{l}</div><div className="mt-1 font-semibold">{v}</div></div>)}</div>{!result.passed && <div className="mt-5 rounded-lg bg-amber-50 p-4 text-left text-sm text-amber-900"><b>Tópicos para revisar:</b> validação inicial, duplicidade e aprovação final.</div>}<p className="mt-5 text-xs">Tentativa {attempts} de {initialGroup.maxAttempts} · SOP {academyProcesses[1].sopVersion}</p><div className="mt-6 flex justify-center gap-3"><Button variant="outline" onClick={onReview}>Revisar conteúdo</Button>{!result.passed && attempts < initialGroup.maxAttempts && <Button onClick={onRetry}>Realizar nova tentativa</Button>}</div></div> }

function GroupEditor({ open, value, onOpenChange, onSave }: { open: boolean; value: TrainingGroup | null; onOpenChange: (open: boolean) => void; onSave: (group: TrainingGroup) => void }) {
  const [draft, setDraft] = useState<TrainingGroup>(value || initialGroup);
  const [step, setStep] = useState("general");
  const [participantSearch, setParticipantSearch] = useState("");
  const [processSearch, setProcessSearch] = useState("");
  useMemo(() => { if (value) { setTimeout(() => { setDraft(value); setStep("general"); }, 0); } }, [value]);
  const set = <K extends keyof TrainingGroup>(key: K, val: TrainingGroup[K]) => setDraft((d) => ({ ...d, [key]: val }));
  const toggleMember = (id: string) => set("participantIds", draft.participantIds.includes(id) ? draft.participantIds.filter((p) => p !== id) : [...draft.participantIds, id]);
  const toggleProcess = (id: string) => set("processIds", draft.processIds.includes(id) ? draft.processIds.filter((p) => p !== id) : [...draft.processIds, id]);
  const validate = (publish: boolean) => { if (!draft.name.trim() || !draft.role.trim() || !draft.department.trim() || !draft.objective.trim() || !draft.owner.trim() || !draft.dueDate) { toast.error("Preencha os campos obrigatórios das informações gerais."); setStep("general"); return false; } if (publish && !draft.participantIds.length) { toast.error("Adicione ao menos um participante antes de publicar."); setStep("participants"); return false; } if (publish && !draft.processIds.length) { toast.error("Vincule ao menos um processo antes de publicar."); setStep("processes"); return false; } return true; };
  const finish = (publish: boolean) => { if (!validate(publish)) return; onSave({ ...draft, status: publish ? "Publicado" : "Rascunho" }); };
  const moveProcess = (id: string, direction: -1 | 1) => { const ids = [...draft.processIds]; const index = ids.indexOf(id); const target = index + direction; if (target < 0 || target >= ids.length) return; [ids[index], ids[target]] = [ids[target], ids[index]]; set("processIds", ids); };
  return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="max-h-[92vh] max-w-5xl overflow-hidden p-0"><DialogHeader className="border-b px-6 py-5"><DialogTitle>{value?.name ? "Editar grupo de treinamento" : "Criar grupo de treinamento"}</DialogTitle><DialogDescription>Configure a trilha usando processos e SOPs existentes no ProcessHub.</DialogDescription></DialogHeader><div className="flex min-h-[560px] overflow-hidden"><nav className="hidden w-52 shrink-0 space-y-1 border-r bg-muted/25 p-3 md:block">{[["general", "1. Informações gerais"], ["participants", "2. Participantes"], ["processes", "3. Processos"], ["settings", "4. Configurações"], ["review", "5. Revisão"]].map(([id, label]) => <button key={id} onClick={() => setStep(id)} className={cn("w-full rounded-lg px-3 py-2.5 text-left text-sm", step === id ? "bg-card font-medium text-primary shadow-sm" : "text-muted-foreground hover:bg-card")}>{label}</button>)}</nav><div className="flex-1 overflow-y-auto p-6">{step === "general" && <div className="grid gap-5 md:grid-cols-2"><Field label="Nome do grupo *" className="md:col-span-2"><Input value={draft.name} onChange={(e) => set("name", e.target.value)} /></Field><Field label="Descrição" className="md:col-span-2"><Textarea value={draft.description} onChange={(e) => set("description", e.target.value)} /></Field><Field label="Cargo ou função *"><Input value={draft.role} onChange={(e) => set("role", e.target.value)} /></Field><Field label="Área *"><Input value={draft.department} onChange={(e) => set("department", e.target.value)} /></Field><Field label="Objetivo do treinamento *" className="md:col-span-2"><Textarea value={draft.objective} onChange={(e) => set("objective", e.target.value)} /></Field><Field label="Responsável *"><Input value={draft.owner} onChange={(e) => set("owner", e.target.value)} /></Field><Field label="Prazo para conclusão *"><Input type="date" value={draft.dueDate} onChange={(e) => set("dueDate", e.target.value)} /></Field></div>}{step === "participants" && <div><div className="relative mb-5"><Search className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" /><Input className="pl-9" placeholder="Pesquisar colaborador..." value={participantSearch} onChange={(e) => setParticipantSearch(e.target.value)} /></div><div className="space-y-2">{academyParticipants.filter((p) => `${p.name} ${p.email}`.toLowerCase().includes(participantSearch.toLowerCase())).map((p) => <label key={p.id} className="flex cursor-pointer items-center gap-4 rounded-xl border p-4 hover:bg-muted/30"><Checkbox checked={draft.participantIds.includes(p.id)} onCheckedChange={() => toggleMember(p.id)} /><div className="flex-1"><div className="text-sm font-medium">{p.name}</div><div className="mt-1 text-xs text-muted-foreground">{p.role} · {p.area} · {p.email}</div></div>{draft.participantIds.includes(p.id) && <span className="text-xs font-medium text-primary">Adicionado</span>}</label>)}</div></div>}{step === "processes" && <div><div className="mb-5 grid gap-3 md:grid-cols-[1fr_180px]"><div className="relative"><Search className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" /><Input className="pl-9" placeholder="Buscar processos cadastrados..." value={processSearch} onChange={(e) => setProcessSearch(e.target.value)} /></div><Select defaultValue="all"><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="all">Todas as áreas</SelectItem></SelectContent></Select></div><div className="space-y-3">{academyProcesses.filter((p) => p.name.toLowerCase().includes(processSearch.toLowerCase())).map((p) => <div key={p.id} className="flex items-center gap-3 rounded-xl border p-4"><Checkbox checked={draft.processIds.includes(p.id)} onCheckedChange={() => toggleProcess(p.id)} /><div className="min-w-0 flex-1"><div className="text-sm font-medium">{p.name}</div><div className="mt-1 text-xs text-muted-foreground">{p.code} · {p.area} · SOP {p.sopVersion} · atualizada em {p.updatedAt} · {p.minutes} min</div></div>{draft.processIds.includes(p.id) && <div className="flex gap-1"><Button size="icon" variant="ghost" aria-label="Mover para cima" onClick={() => moveProcess(p.id, -1)}>↑</Button><Button size="icon" variant="ghost" aria-label="Mover para baixo" onClick={() => moveProcess(p.id, 1)}>↓</Button><Button size="sm" variant="outline" onClick={() => toast.info(`SOP ${p.sopVersion} aberta em modo de visualização.`)}>Ver SOP</Button></div>}</div>)}</div></div>}{step === "settings" && <div className="grid gap-5 md:grid-cols-2"><Field label="Nota mínima para aprovação"><Input type="number" min={0} max={100} value={draft.passingScore} onChange={(e) => set("passingScore", Number(e.target.value))} /></Field><Field label="Número máximo de tentativas"><Input type="number" min={1} value={draft.maxAttempts} onChange={(e) => set("maxAttempts", Number(e.target.value))} /></Field><Setting label="Permitir novas tentativas" checked={draft.allowRetries} onChange={(v) => set("allowRetries", v)} /><Setting label="Exigir leitura completa" checked={draft.requireReading} onChange={(v) => set("requireReading", v)} /><Setting label="Exigir registro de ciência" checked={draft.requireAcknowledgment} onChange={(v) => set("requireAcknowledgment", v)} /><Setting label="Exigir aprovação no quiz" checked={draft.requireQuiz} onChange={(v) => set("requireQuiz", v)} /><Setting label="Emitir certificação ao concluir" checked={draft.issueCertificate} onChange={(v) => set("issueCertificate", v)} /></div>}{step === "review" && <div><div className="rounded-xl border bg-muted/25 p-5"><h3 className="text-lg font-semibold">{draft.name || "Grupo sem nome"}</h3><p className="mt-2 text-sm">{draft.objective || "Objetivo não informado"}</p><div className="mt-5 grid gap-4 sm:grid-cols-2"><SummaryRow label="Público" value={`${draft.participantIds.length} participantes · ${draft.role || "Cargo não informado"}`} /><SummaryRow label="Trilha" value={`${draft.processIds.length} processos vinculados`} /><SummaryRow label="Regras" value={`Nota ${draft.passingScore}% · ${draft.maxAttempts} tentativas · leitura ${draft.requireReading ? "obrigatória" : "opcional"}`} /><SummaryRow label="Prazo" value={draft.dueDate ? new Date(`${draft.dueDate}T12:00:00`).toLocaleDateString("pt-BR") : "Não informado"} /></div></div>{(!draft.participantIds.length || !draft.processIds.length) && <div className="mt-4 rounded-lg border border-amber-200 bg-amber-50 p-4 text-sm text-amber-900">Para publicar, adicione pelo menos um participante e um processo. Você ainda pode salvar como rascunho.</div>}</div>}</div></div><DialogFooter className="border-t px-6 py-4"><div className="flex w-full flex-col-reverse justify-between gap-3 sm:flex-row"><Button variant="ghost" onClick={() => onOpenChange(false)}>Cancelar</Button><div className="flex gap-2"><Button variant="outline" onClick={() => finish(false)}>Salvar como rascunho</Button><Button onClick={() => finish(true)}>Publicar grupo</Button></div></div></DialogFooter></DialogContent></Dialog>;
}

function Field({ label, children, className }: { label: string; children: React.ReactNode; className?: string }) { return <div className={className}><Label>{label}</Label><div className="mt-2">{children}</div></div> }
function Setting({ label, checked, onChange }: { label: string; checked: boolean; onChange: (value: boolean) => void }) { return <div className="flex items-center justify-between rounded-xl border p-4"><Label>{label}</Label><Switch checked={checked} onCheckedChange={onChange} /></div> }
